DISCLAIMER: **The below code is AI generated and untested!!**

The code below helps explain the direction I think would work best for this:
- Compare previous entitlements with current
- Fire two different pixels reporting removed and added entitlements.

Note: Besides removed entitlements, knowing about added entitlements would be valuable as well.

```swift
extension NotificationCenter.Publisher {
    // Just a convenience publisher to scan previous value... this can actually be moved inline if preferred.
    func trackPreviousEntitlements() -> AnyPublisher<([Entitlement], [Entitlement]?), Never> {
        scan((current: [Entitlement](), previous: [Entitlement]?.none)) { state, notification in
            let userInfo = notification.userInfo as? [AnyHashable: [Entitlement]]
            let currentEntitlements = userInfo?[UserDefaultsCacheKey.subscriptionEntitlements] ?? []
            return (current: currentEntitlements, previous: state.current)
        }
        .eraseToAnyPublisher()
    }
}

let cancellable = NotificationCenter.default
    .publisher(for: .entitlementsDidChange)
    .trackPreviousEntitlements()
    .sink { current, previous in
        let currentEntitlements = current
        let previousEntitlements = previous ?? []
        
        // Get the product names, excluding .unknown
        let currentProducts = Set(currentEntitlements.map(\.product).filter { $0 != .unknown })
        let previousProducts = Set(previousEntitlements.map(\.product).filter { $0 != .unknown })
        
        // Find products that were in previous but not in current (removed)
        let removedProducts = previousProducts.subtracting(currentProducts)
        
        // Find products that are in current but were not in previous (added)
        let addedProducts = currentProducts.subtracting(previousProducts)
        
        // Fire pixel for removed products
        if !removedProducts.isEmpty {
            let removedProductsDescription = removedProducts.map(\.rawValue).sorted().joined(separator: ", ")
            let entitlementsDescriptions = currentEntitlements.map(\.product.rawValue).sorted().joined(separator: ", ")
            PixelKit.fire(
                PrivacyProPixel.privacyProEntitlementsRemoved(removedProductsDescription, entitlementsDescriptions),
                frequency: .dailyAndCount
            )
        }
        
        // Fire pixel for added products
        if !addedProducts.isEmpty {
            let addedProductsDescription = addedProducts.map(\.rawValue).sorted().joined(separator: ", ")
            let entitlementsDescriptions = currentEntitlements.map(\.product.rawValue).sorted().joined(separator: ", ")
            PixelKit.fire(
                PrivacyProPixel.privacyProEntitlementsAdded(addedProductsDescription, entitlementsDescriptions),
                frequency: .dailyAndCount
            )
        }
    }
